INSERT INTO dbo.VideoTranscripts (Transcript_ID, Video_ID, Recipe_ID, Raw_Transcript, Extracted_Recipe_JSON, AI_Summary, STT_Model_Version, Status, Created_At, Completed_At) VALUES
(10001, 10001, 10094, N'Chào các bạn, hôm nay mình hướng dẫn nấu Cơm Cuộn Chay. Bước 1. Nấm hương, cà rốt, măng sau khi sơ chế sạch đem cắt hạt lựu. Nếu dùng nấm khô, bạn ngâm vào nước ấm khoảng 30 phút trước khi làm cho nấm mềm. Làm nóng chảo với chút dầu láng mặt, chờ dầu nóng thì trút nấm, cà rốt, măng vào xào sơ, nêm 1 xíu muối, đảo lại trong giây lát rồi tắt lửa. Bước 2. Cơm trắng cho vào tô lớn, thêm 1,5 muỗng cà phê dầu mè, 1 muỗng cà phê muối, ½ muỗng cà phê hạt tiêu trắng vào trộn đều. Kế đó cho nấm, cà rốt và măng vào trộn đều. Bước 3. Trứng đập ra bát, đánh tan. Trải tấm phù trúc lên mặt thớt rộng, dùng cọ quết một lớp trứng mỏng đều lên tấm phù trúc. Múc cơm vào giữa tấm phù trúc rồi dàn thành một lớp thật đều dày chừng 0.5cm, nhưng không dàn cơm khắp mặt tấm phù trúc mà chừa lại chừng 5cm ở phần mép ngoài để giúp cuộn cơm dễ dàng và kết dính tốt hơn. Đặt mấy quả đậu cô ve đã luộc chín vào vị trí 1/3 của cuộn cơm. Bước 4. Nhấc mép phù trúc, từ từ cuốn lại như thao tác gói nem, lực cuốn vừa tay không lỏng cũng không chặt quá. Ở đoạn phù trúc cuối cùng mà bạn để thừa lại lúc trước, bạn dùng cọ quết một lớp trứng mỏng lên rồi mới cuộn lại để giúp cố định mép cuốn. Sau cùng, tiếp tục dùng cọ quết một lớp trứng mỏng lên khắp cuộn cơm. Bước 5. Lăn cuốn cơm qua bột xù. Lưu ý, nên bóp vụn phần bột xù để giúp bột bám dính tốt hơn. Thêm vào đó không chỉ lăn cuốn cơm 1 lần mà nên 2,3 lần qua trứng và bột xù để tạo thành một lớp bột dày hơn xung quanh cuốn thịt. Trong quá trình cuốn, nhớ dùng lực ấn nhẹ để bột bám chắc lên bề mặt. Đặt cuốn cơm vào giữa tấm giấy bạc, gói kín lại. Làm nóng lò trước đến 180 độ rồi mới đặt cuộn cơm vào, nướng trong khoảng 12 phút. Cuộn cơm lấy ra cắt thành từng khoanh dày chừng 1.5cm, xếp lên đĩa. Ghi chú – Bản tăng cân: tăng đạm thực vật, tinh bột và chất béo tốt; có thể ăn kèm hạt/đậu phộng rang. Chúc các bạn thành công!', N'{"title":"Cơm Cuộn Chay","servings":2,"cookTimeMinutes":64,"ingredients":[{"name":"Trứng gà ta tươi","quantity":50.0},{"name":"Tàu hũ ky khô","quantity":30.0},{"name":"Đậu que","quantity":350.0},{"name":"Nấm hương tươi","quantity":10.0},{"name":"Cà rốt củ tươi","quantity":100.0},{"name":"Măng tươi luộc chín","quantity":30.0},{"name":"Hạt mè trắng","quantity":5.0},{"name":"Gạo thơm lài miên","quantity":200.0},{"name":"Bột mì đa dụng","quantity":50.0},{"name":"Dầu đậu nành nguyên chất","quantity":25.0},{"name":"Muối tinh","quantity":5.0},{"name":"Tiêu đen xay nguyên chất","quantity":1.0}],"steps":["Bước 1. Nấm hương, cà rốt, măng sau khi sơ chế sạch đem cắt hạt lựu. Nếu dùng nấm khô, bạn ngâm vào nước ấm khoảng 30 phút trước khi làm cho nấm mềm. Làm nóng chảo với chút dầu láng mặt, chờ dầu nóng thì trút nấm, cà rốt, măng vào xào sơ, nêm 1 xíu muối, đảo lại trong giây lát rồi tắt lửa.","Bước 2. Cơm trắng cho vào tô lớn, thêm 1,5 muỗng cà phê dầu mè, 1 muỗng cà phê muối, ½ muỗng cà phê hạt tiêu trắng vào trộn đều. Kế đó cho nấm, cà rốt và măng vào trộn đều.","Bước 3. Trứng đập ra bát, đánh tan. Trải tấm phù trúc lên mặt thớt rộng, dùng cọ quết một lớp trứng mỏng đều lên tấm phù trúc. Múc cơm vào giữa tấm phù trúc rồi dàn thành một lớp thật đều dày chừng 0.5cm, nhưng không dàn cơm khắp mặt tấm phù trúc mà chừa lại chừng 5cm ở phần mép ngoài để giúp cuộn cơm dễ dàng và kết dính tốt hơn. Đặt mấy quả đậu cô ve đã luộc chín vào vị trí 1/3 của cuộn cơm.","Bước 4. Nhấc mép phù trúc, từ từ cuốn lại như thao tác gói nem, lực cuốn vừa tay không lỏng cũng không chặt quá. Ở đoạn phù trúc cuối cùng mà bạn để thừa lại lúc trước, bạn dùng cọ quết một lớp trứng mỏng lên rồi mới cuộn lại để giúp cố định mép cuốn. Sau cùng, tiếp tục dùng cọ quết một lớp trứng mỏng lên khắp cuộn cơm.","Bước 5. Lăn cuốn cơm qua bột xù. Lưu ý, nên bóp vụn phần bột xù để giúp bột bám dính tốt hơn. Thêm vào đó không chỉ lăn cuốn cơm 1 lần mà nên 2,3 lần qua trứng và bột xù để tạo thành một lớp bột dày hơn xung quanh cuốn thịt. Trong quá trình cuốn, nhớ dùng lực ấn nhẹ để bột bám chắc lên bề mặt. Đặt cuốn cơm vào giữa tấm giấy bạc, gói kín lại. Làm nóng lò trước đến 180 độ rồi mới đặt cuộn cơm vào, nướng trong khoảng 12 phút. Cuộn cơm lấy ra cắt thành từng khoanh dày chừng 1.5cm, xếp lên đĩa.","Ghi chú – Bản tăng cân: tăng đạm thực vật, tinh bột và chất béo tốt; có thể ăn kèm hạt/đậu phộng rang."],"tips":["Chọn nguyên liệu tươi để món ngon hơn."]}', N'Hướng dẫn nấu Cơm Cuộn Chay với 12 nguyên liệu chính, khoảng 746 kcal mỗi khẩu phần.', 'whisper-large-v3', 'COMPLETED', DATEADD(MINUTE,-22888,@Now), DATEADD(MINUTE,-22886,@Now)),
(10002, 10002, 10070, N'Chào các bạn, hôm nay mình hướng dẫn nấu Đậu Hũ Sốt Chay. 1: Nấm hương rửa sạch, ngâm nước cho nở. Bước 2: Thái nhỏ hoặc băm nhỏ nấm. Bước 3: Đậu phụ bỏ ra khỏi hộp, xắt miếng nhỏ vừa ăn. Bước 4: Bắc chảo lên bếp, cho dầu ăn vào và xào nấm hương chín. Bước 5: Tiếp tục cho sa tế chay và ớt bột vào đảo đều, lấy 2 thìa canh nước ngâm nấm hương thêm vào chảo, để sôi, nêm nếm muối, đường cho vừa miệng. Bước 6: Cho đậu non vào chảo, thi thoảng lắc nhẹ chảo để đậu ngấm gia vị, không đảo bằng đũa để tránh miếng đậu bị nát. Bước 7: Khi đậu non sôi, ngấm đủ gia vị thì tắt bếp, dùng nóng sẽ ngon hơn. Ghi chú – Bản giảm cân: giảm dầu mỡ, đường và tinh bột, tăng lượng rau củ; ăn chậm, nhai kỹ. Chúc các bạn thành công!', N'{"title":"Đậu Hũ Sốt Chay","servings":2,"cookTimeMinutes":36,"ingredients":[{"name":"Đậu hũ non","quantity":985.0},{"name":"Nấm hương tươi","quantity":320.0},{"name":"Dầu hào chay nấm hương","quantity":19.5},{"name":"Muối tinh","quantity":3.9},{"name":"Đường cát trắng","quantity":4.0},{"name":"Ớt hiểm tươi cay","quantity":6.5}],"steps":["1: Nấm hương rửa sạch, ngâm nước cho nở.","Bước 2: Thái nhỏ hoặc băm nhỏ nấm.","Bước 3: Đậu phụ bỏ ra khỏi hộp, xắt miếng nhỏ vừa ăn.","Bước 4: Bắc chảo lên bếp, cho dầu ăn vào và xào nấm hương chín.","Bước 5: Tiếp tục cho sa tế chay và ớt bột vào đảo đều, lấy 2 thìa canh nước ngâm nấm hương thêm vào chảo, để sôi, nêm nếm muối, đường cho vừa miệng.","Bước 6: Cho đậu non vào chảo, thi thoảng lắc nhẹ chảo để đậu ngấm gia vị, không đảo bằng đũa để tránh miếng đậu bị nát.","Bước 7: Khi đậu non sôi, ngấm đủ gia vị thì tắt bếp, dùng nóng sẽ ngon hơn.","Ghi chú – Bản giảm cân: giảm dầu mỡ, đường và tinh bột, tăng lượng rau củ; ăn chậm, nhai kỹ."],"tips":["Chọn nguyên liệu tươi để món ngon hơn."]}', N'Hướng dẫn nấu Đậu Hũ Sốt Chay với 6 nguyên liệu chính, khoảng 342 kcal mỗi khẩu phần.', 'whisper-large-v3', 'COMPLETED', DATEADD(MINUTE,-78445,@Now), DATEADD(MINUTE,-78443,@Now)),
(10003, 10003, 10155, N'Chào các bạn, hôm nay mình hướng dẫn nấu Đậu Hủ Sốt Cay. Đậu hũ rửa sạch cắt miếng vuông mỏng. Bột ngô bỏ ra đĩa, gắp từng miếng đậu tẩm qua bột rồi cho vào chảo dầu nóng rán vàng, bột chỉ cần bám sơ quanh miếng đậu là được. Khi rán đậu chú ý để lửa nhỏ để tránh bột bị cháy. Đậu rán chín vàng hai mặt thì cho ra đĩa, để sang một bên. Cho một chút nước nếu chảo quá khô và để tránh cà chua bị cháy. Tiếp theo cho đậu rán vào chảo, thêm nửa chén nước, rồi mở lửa to đun sôi, nêm nếm lại bột canh cho vừa ăn. Nhỏ lửa âm ỉ cho đậu ngấm gia vị. Đun đến khi nước cạn bớt là được. Khi đun tránh dùng đũa đảo nhiều, đậu sẽ bị vỡ. Xúc đậu ra bát to, rắc hạt tiêu lên trên, món chay ăn nóng với cơm. Ghi chú – Bản giữ cân: khẩu phần cân đối đạm – tinh bột – rau củ. Bản không hành tỏi (hợp người ăn chay kiêng ngũ vị tân): bỏ hành, tỏi, hẹ, boa rô. Chúc các bạn thành công!', N'{"title":"Đậu Hủ Sốt Cay","servings":2,"cookTimeMinutes":39,"ingredients":[{"name":"Đậu hũ trắng","quantity":300.0},{"name":"Nấm rơm tươi","quantity":300.0},{"name":"Cà chua chín đỏ","quantity":75.0},{"name":"Bột bắp","quantity":50.0},{"name":"Hạt nêm nấm chay bào ngư","quantity":2.5},{"name":"Dầu đậu nành nguyên chất","quantity":50.0},{"name":"Đường cát trắng","quantity":8.0},{"name":"Tiêu đen xay nguyên chất","quantity":1.0},{"name":"Ớt hiểm tươi cay","quantity":10.0}],"steps":["Đậu hũ rửa sạch cắt miếng vuông mỏng. Bột ngô bỏ ra đĩa, gắp từng miếng đậu tẩm qua bột rồi cho vào chảo dầu nóng rán vàng, bột chỉ cần bám sơ quanh miếng đậu là được.","Khi rán đậu chú ý để lửa nhỏ để tránh bột bị cháy. Đậu rán chín vàng hai mặt thì cho ra đĩa, để sang một bên.","Cho một chút nước nếu chảo quá khô và để tránh cà chua bị cháy.","Tiếp theo cho đậu rán vào chảo, thêm nửa chén nước, rồi mở lửa to đun sôi, nêm nếm lại bột canh cho vừa ăn. Nhỏ lửa âm ỉ cho đậu ngấm gia vị.","Đun đến khi nước cạn bớt là được. Khi đun tránh dùng đũa đảo nhiều, đậu sẽ bị vỡ. Xúc đậu ra bát to, rắc hạt tiêu lên trên, món chay ăn nóng với cơm.","Ghi chú – Bản giữ cân: khẩu phần cân đối đạm – tinh bột – rau củ. Bản không hành tỏi (hợp người ăn chay kiêng ngũ vị tân): bỏ hành, tỏi, hẹ, boa rô."],"tips":["Chọn nguyên liệu tươi để món ngon hơn."]}', N'Hướng dẫn nấu Đậu Hủ Sốt Cay với 9 nguyên liệu chính, khoảng 504 kcal mỗi khẩu phần.', 'whisper-large-v3', 'COMPLETED', DATEADD(MINUTE,-6740,@Now), DATEADD(MINUTE,-6738,@Now)),
(10004, 10004, 10057, N'Chào các bạn, hôm nay mình hướng dẫn nấu Đậu Hũ La Hán. Cắt miếng dăm bông chay ra thành các lát mỏng, Tiếp theo, xắt miếng đậu hũ non thành các miếng hình chữ nhật. Khi làm món ăn này thì các bạn nên chọn mua đậu hũ non để chế biến món ăn, vì đậu hũ non rất mềm, dễ ăn, dễ chế biến – phù hợp với món chay. Sau khi cải chín thì vớt cải ra một tô nước lạnh, nồi nước luộc đang sôi, cho tiếp nấm đông cô và trần sơ qua rồi cũng đổ nấm vào tô nước lạnh đang ngâm cải. Nấm đông cô tươi mua về chỉ nên cắt bỏ một chút châm nấm ở dưới thân rồi ngâm với nước ấm có cho 1 thìa café muối nhỏ. Bạn có thể khía các đường đồng tâm trên đỉnh nấm để tạo hoa đẹp mắt. Cải thìa nhặt và rửa sạch lá úa, lá bẩn. Chuẩn bị một nồi nước để luộc cải thìa nguyên cây. Bí quyết luộc cải ngon và đẹp mắt là bạn cho 1 thìa café dầu ăn và ½ thìa café muối vào nồi nước luộc. Khi cải chín vớt ra sẽ xanh hơn, nhìn ngọn cải mướt và rất bóng mượt, đẹp mắt. Vớt rau và nấm ra để ráo. Cải thìa dùng dao chẻ đôi dọc theo thân cây để vừa ăn. Gừng cạo vỏ và rửa sạch, để ráo nước, thái lát. Gừng này giúp món ăn chay của bạn giảm bớt tính hàn, cân bằng tính hàn- nhiệt của món ăn và giúp món ăn thơm ngon hơn. Sau khi sơ chế xong nguyên liệu. Chuẩn bị một nồi nước để hấp. Sắp cải đều lên ½ diện tích của đĩa, ½ đĩa còn lại đặt một miếng đậu, xen kẽ một miếng dăm bông thịt nguội, xen kẽ một cây nấm, xen kẽ một lát gừng. Lấy một chiếc bát to để pha nước sốt với công thức: 1,5 muỗng canh dầu hào chay, ½ muỗng canh nước tương, 1/3 muỗng canh tiêu, 1 muỗng canh đường, 1 muỗng café đường, 1 chút tiêu, ½ muỗng dầu mè, 1,5 muỗng nước lọc, 1,5 muỗng café bột năng. Trộn đều cho đến khi các gia vị tan ra và hòa đều vào nhau. Rưới nước sốt đều lên trên mặt đĩa đậu phụ đã sắp, rắc cùng với một chút kì tử. Cho vào nồi nước sôi để hấp cách thủy. Sau mười phút là món ăn của bạn hoàn thành rồi đấy. Ghi chú – Bản giảm cân: giảm dầu mỡ, đường và tinh bột, tăng lượng rau củ; ăn chậm, nhai kỹ. Chúc các bạn thành công!', N'{"title":"Đậu Hũ La Hán","servings":2,"cookTimeMinutes":42,"ingredients":[{"name":"Đậu hũ non","quantity":200.0},{"name":"Nấm hương tươi","quantity":100.0},{"name":"Cải thìa tươi","quantity":200.0},{"name":"Hạt mè trắng","quantity":10.0},{"name":"Bột năng","quantity":20.0},{"name":"Bột bắp","quantity":20.0},{"name":"Nước tương đậu nành","quantity":15.0},{"name":"Hạt nêm nấm chay bào ngư","quantity":5.0},{"name":"Dầu đậu nành nguyên chất","quantity":30.0},{"name":"Đường cát trắng","quantity":8.0},{"name":"Tiêu đen xay nguyên chất","quantity":1.0},{"name":"Gừng củ tươi","quantity":60.0}],"steps":["Cắt miếng dăm bông chay ra thành các lát mỏng,","Tiếp theo, xắt miếng đậu hũ non thành các miếng hình chữ nhật. Khi làm món ăn này thì các bạn nên chọn mua đậu hũ non để chế biến món ăn, vì đậu hũ non rất mềm, dễ ăn, dễ chế biến – phù hợp với món chay.","Sau khi cải chín thì vớt cải ra một tô nước lạnh, nồi nước luộc đang sôi, cho tiếp nấm đông cô và trần sơ qua rồi cũng đổ nấm vào tô nước lạnh đang ngâm cải.","Nấm đông cô tươi mua về chỉ nên cắt bỏ một chút châm nấm ở dưới thân rồi ngâm với nước ấm có cho 1 thìa café muối nhỏ. Bạn có thể khía các đường đồng tâm trên đỉnh nấm để tạo hoa đẹp mắt.","Cải thìa nhặt và rửa sạch lá úa, lá bẩn. Chuẩn bị một nồi nước để luộc cải thìa nguyên cây. Bí quyết luộc cải ngon và đẹp mắt là bạn cho 1 thìa café dầu ăn và ½ thìa café muối vào nồi nước luộc. Khi cải chín vớt ra sẽ xanh hơn, nhìn ngọn cải mướt và rất bóng mượt, đẹp mắt.","Vớt rau và nấm ra để ráo. Cải thìa dùng dao chẻ đôi dọc theo thân cây để vừa ăn. Gừng cạo vỏ và rửa sạch, để ráo nước, thái lát. Gừng này giúp món ăn chay của bạn giảm bớt tính hàn, cân bằng tính hàn- nhiệt của món ăn và giúp món ăn thơm ngon hơn.","Sau khi sơ chế xong nguyên liệu. Chuẩn bị một nồi nước để hấp. Sắp cải đều lên ½ diện tích của đĩa, ½ đĩa còn lại đặt một miếng đậu, xen kẽ một miếng dăm bông thịt nguội, xen kẽ một cây nấm, xen kẽ một lát gừng.","Lấy một chiếc bát to để pha nước sốt với công thức: 1,5 muỗng canh dầu hào chay, ½ muỗng canh nước tương, 1/3 muỗng canh tiêu, 1 muỗng canh đường, 1 muỗng café đường, 1 chút tiêu, ½ muỗng dầu mè, 1,5 muỗng nước lọc, 1,5 muỗng café bột năng. Trộn đều cho đến khi các gia vị tan ra và hòa đều vào nhau.","Rưới nước sốt đều lên trên mặt đĩa đậu phụ đã sắp, rắc cùng với một chút kì tử. Cho vào nồi nước sôi để hấp cách thủy. Sau mười phút là món ăn của bạn hoàn thành rồi đấy.","Ghi chú – Bản giảm cân: giảm dầu mỡ, đường và tinh bột, tăng lượng rau củ; ăn chậm, nhai kỹ."],"tips":["Chọn nguyên liệu tươi để món ngon hơn."]}', N'Hướng dẫn nấu Đậu Hũ La Hán với 12 nguyên liệu chính, khoảng 371 kcal mỗi khẩu phần.', 'whisper-large-v3', 'COMPLETED', DATEADD(MINUTE,-64970,@Now), DATEADD(MINUTE,-64968,@Now)),
(10005, 10005, 10136, N'Chào các bạn, hôm nay mình hướng dẫn nấu Chả Giò Chay. Bước 1: Cho tất cả các nguyên liệu đã sơ chế vào âu lớn. Thêm một muỗng cafe hạt tiêu, 2 muỗng cà phê đường và 2 muỗng cafe bột ngọt cùng với 1 muỗng cafe bột gạo. Đảo cho nguyên liệu và gia vị đều. Bước 2: Bánh tráng cuốn nhúng qua nước cho mềm sau đó cho phần nhân và cuốn lại. (Bạn nên hòa 3 muỗng cafe bột gạo với 20ml nước dùng để dán bánh tráng cho khỏi bị bung ra khi bạn chiên.) Lưu ý: Khi cuốn nhẹ tay để chả giò sẽ nở khi chiên. Bước 3: Cho nhiều dầu ăn vào chảo bắc lên bếp đun sôi thì cho từng thanh chả giò vào chiên. Khi chả giò nổi lên và vàng giòn thì vớt chả giò ra giấy thấm dầu. Chả giò chay có thể ăn với tương cà hay ăn với nước tương dùng chung với bún sẽ rất ngon ngon. Ghi chú – Bản giảm cân: giảm dầu mỡ, đường và tinh bột, tăng lượng rau củ; ăn chậm, nhai kỹ. Chúc các bạn thành công!', N'{"title":"Chả Giò Chay","servings":2,"cookTimeMinutes":42,"ingredients":[{"name":"Đậu hũ trắng","quantity":85.0},{"name":"Đậu xanh bóc vỏ","quantity":55.0},{"name":"Nấm mộc nhĩ khô","quantity":15.0},{"name":"Cà rốt củ tươi","quantity":100.0},{"name":"Khoai tây tươi","quantity":40.0},{"name":"Khoai môn cao","quantity":35.0},{"name":"Củ sắn tươi","quantity":65.0},{"name":"Gạo thơm lài miên","quantity":55.0},{"name":"Bánh tráng gỏi cuốn","quantity":10.0},{"name":"Hạt nêm nấm chay bào ngư","quantity":6.5},{"name":"Dầu đậu nành nguyên chất","quantity":7.5},{"name":"Đường cát trắng","quantity":4.0},{"name":"Tiêu đen xay nguyên chất","quantity":1.3}],"steps":["Bước 1: Cho tất cả các nguyên liệu đã sơ chế vào âu lớn. Thêm một muỗng cafe hạt tiêu, 2 muỗng cà phê đường và 2 muỗng cafe bột ngọt cùng với 1 muỗng cafe bột gạo. Đảo cho nguyên liệu và gia vị đều.","Bước 2: Bánh tráng cuốn nhúng qua nước cho mềm sau đó cho phần nhân và cuốn lại. (Bạn nên hòa 3 muỗng cafe bột gạo với 20ml nước dùng để dán bánh tráng cho khỏi bị bung ra khi bạn chiên.)","Lưu ý: Khi cuốn nhẹ tay để chả giò sẽ nở khi chiên.","Bước 3: Cho nhiều dầu ăn vào chảo bắc lên bếp đun sôi thì cho từng thanh chả giò vào chiên. Khi chả giò nổi lên và vàng giòn thì vớt chả giò ra giấy thấm dầu. Chả giò chay có thể ăn với tương cà hay ăn với nước tương dùng chung với bún sẽ rất ngon ngon.","Ghi chú – Bản giảm cân: giảm dầu mỡ, đường và tinh bột, tăng lượng rau củ; ăn chậm, nhai kỹ."],"tips":["Chọn nguyên liệu tươi để món ngon hơn."]}', N'Hướng dẫn nấu Chả Giò Chay với 13 nguyên liệu chính, khoảng 379 kcal mỗi khẩu phần.', 'whisper-large-v3', 'COMPLETED', DATEADD(MINUTE,-14451,@Now), DATEADD(MINUTE,-14449,@Now)),
(10006, 10006, 10117, N'Chào các bạn, hôm nay mình hướng dẫn nấu Canh Chua Chay. làm:Sơ chế: Đậu hũ non cắt ra miếng vừa ăn. Có thể chia bớt 1 phần xắt mỏng đem chiên giòn để sau cùng bỏ vào nồi canh cho phong phú. Cà chua bổ múi cau làm 6 miếng Dứa chia đôi: 1 phần bằm nhuyễn, 1 phần xắt lát mỏng Đậu bắp xắt khúc vừa ăn Dọc mùng cắt xéo khúc vừa ăn. Sau đó cho vào tô nước có pha chút muối, bóp 1 chút rồi rửa lại bằng nước sạch, làm vậy để không bị ngứa. Tỏi tây thái nhỏ. Ngò xắt khúc. Đầu tiên ngâm vắt me vào trong cái chén nước ấm, dằm nhẹ cho ra nước chua (dằm mạnh cũng không sao). Bắc cái nồi đủ nấu canh, cho vào chút dầu ăn, rồi thả vài lát boa rô vào phi thơm, sau đó cho phần dứa băm vào xào cho chín, ra nước vàng, rồi cho tiếp cà chua và dứa lát vào xào sơ vài phát cho vui (buồn thì đừng xào nha :))) . Rồi mới đổ 1 lượng nước đủ nấu canh vào nồi, trút hết nấm vô luôn, nấu sôi. Ghi chú – Bản tăng cân: tăng đạm thực vật, tinh bột và chất béo tốt; có thể ăn kèm hạt/đậu phộng rang. Chúc các bạn thành công!', N'{"title":"Canh Chua Chay","servings":2,"cookTimeMinutes":36,"ingredients":[{"name":"Đậu hũ non","quantity":1575.0},{"name":"Đậu bắp tươi","quantity":1025.0},{"name":"Nấm rơm tươi","quantity":290.0},{"name":"Cà chua chín đỏ","quantity":440.0},{"name":"Dứa","quantity":220.0},{"name":"Me chua","quantity":20.0},{"name":"Muối tinh","quantity":3.0},{"name":"Đường cát trắng","quantity":8.0}],"steps":["làm:Sơ chế:","Đậu hũ non cắt ra miếng vừa ăn. Có thể chia bớt 1 phần xắt mỏng đem chiên giòn để sau cùng bỏ vào nồi canh cho phong phú.","Cà chua bổ múi cau làm 6 miếng","Dứa chia đôi: 1 phần bằm nhuyễn, 1 phần xắt lát mỏng","Đậu bắp xắt khúc vừa ăn","Dọc mùng cắt xéo khúc vừa ăn. Sau đó cho vào tô nước có pha chút muối, bóp 1 chút rồi rửa lại bằng nước sạch, làm vậy để không bị ngứa.","Tỏi tây thái nhỏ. Ngò xắt khúc.","Đầu tiên ngâm vắt me vào trong cái chén nước ấm, dằm nhẹ cho ra nước chua (dằm mạnh cũng không sao).","Bắc cái nồi đủ nấu canh, cho vào chút dầu ăn, rồi thả vài lát boa rô vào phi thơm, sau đó cho phần dứa băm vào xào cho chín, ra nước vàng, rồi cho tiếp cà chua và dứa lát vào xào sơ vài phát cho vui (buồn thì đừng xào nha :))) .","Rồi mới đổ 1 lượng nước đủ nấu canh vào nồi, trút hết nấm vô luôn, nấu sôi.","Ghi chú – Bản tăng cân: tăng đạm thực vật, tinh bột và chất béo tốt; có thể ăn kèm hạt/đậu phộng rang."],"tips":["Chọn nguyên liệu tươi để món ngon hơn."]}', N'Hướng dẫn nấu Canh Chua Chay với 8 nguyên liệu chính, khoảng 781 kcal mỗi khẩu phần.', 'whisper-large-v3', 'COMPLETED', DATEADD(MINUTE,-57774,@Now), DATEADD(MINUTE,-57772,@Now));
